102	/* Per-command gate for the VelaGuard tools.  This has to live in C rather
103	 * than in the skill text: these commands are reachable through the generic
104	 * run_shell tool, and vgstats inject/reset mutate frame counters, vgnet
105	 * inject/wifi rewrite network policy, and vgruntime report <path> writes an
106	 * arbitrary file.
107	 *
108	 *   subcmd == NULL  read-only by construction, the whole command is fine
109	 *   subcmd == ""    no subcommand is permitted at all
110	 *   otherwise       the first token after the command must equal subcmd   */
111	
112	static const struct {
113	    const char *name;
114	    const char *subcmd;
115	} s_vg_readonly[] = {
116	    { "vgmodbus",   NULL     },
117	    { "vgstats",    "dump"   },
118	    { "vgruntime",  "dump"   },
119	    { "vgcfg",      "dump"   },
120	    { "vgnet",      "status" },
121	    { "vgpoint",    ""       },
122	    { "vgdiscover", ""       },
123	    { NULL, NULL }
124	};
