127	/* Shell meta-characters that could be used for injection */
128	#if AGENT_SHELL_SECURITY == AGENT_SHELL_SECURITY_ALLOWLIST
129	static bool has_shell_meta(const char *cmd)
130	{
131	    const char *meta = "|;&`$(){}><\n\\";
132	    for (const char *p = cmd; *p; p++) {
133	        if (strchr(meta, *p)) return true;
134	    }
135	    return false;
136	}
137	#endif
