139	static int is_blocked(const char *cmd)
140	{
141	#if AGENT_SHELL_SECURITY == AGENT_SHELL_SECURITY_DENY
142	    /* Deny mode: block everything */
143	    return 1;
144	#elif AGENT_SHELL_SECURITY == AGENT_SHELL_SECURITY_FULL
145	    /* Full mode: allow most commands, only block critical ones.
146	     * This mode is designed for skill authoring and development.
147	     * Skills can use pipes, redirects, and command chaining. */
148	    
149	    /* Extract command name */
150	    char first[64];
151	    int i = 0;
152	    while (cmd[i] == ' ') i++;
153	    int j = 0;
154	    while (cmd[i] && cmd[i] != ' ' && j < (int)sizeof(first) - 1)
155	        first[j++] = cmd[i++];
156	    first[j] = '\0';
157	
158	    /* Strip path prefix: /bin/rm -> rm */
159	    const char *basename = strrchr(first, '/');
160	    const char *name = basename ? basename + 1 : first;
161	
162	    /* Block critical commands only */
163	    for (int k = 0; s_critical[k]; k++) {
164	        if (strcmp(name, s_critical[k]) == 0)
165	            return 1;
166	    }
167	    
168	    return 0;  /* allow */
169	#else
170	    /* Allowlist mode (default): strict whitelist + no shell meta-characters.
171	     * This is the production-safe mode. */
172	    
173	    /* Reject any shell meta-characters (pipe, redirect, subshell, etc.) */
174	    if (has_shell_meta(cmd))
175	        return 1;
176	
177	    /* Extract the first token (command name) */
178	    char first[64];
179	    int i = 0;
180	    while (cmd[i] == ' ') i++;
181	    int j = 0;
182	    while (cmd[i] && cmd[i] != ' ' && j < (int)sizeof(first) - 1)
183	        first[j++] = cmd[i++];
184	    first[j] = '\0';
185	
186	    /* Strip path prefix: /bin/rm -> rm, /usr/bin/dd -> dd */
187	    const char *basename = strrchr(first, '/');
188	    const char *name = basename ? basename + 1 : first;
189	
190	    /* VelaGuard: the agent may read board state, never change it. */
191	    for (int k = 0; s_vg_readonly[k].name; k++) {
192	        if (strcmp(name, s_vg_readonly[k].name) != 0)
193	            continue;
194	
195	        const char *want = s_vg_readonly[k].subcmd;
196	
197	        if (want == NULL)
198	            return 0;           /* read-only by construction */
199	
200	        if (want[0] == '\0')
201	            return 1;           /* nothing permitted, including bare name */
202	
203	        while (cmd[i] == ' ') i++;
204	        size_t wlen = strlen(want);
205	        if (strncmp(cmd + i, want, wlen) != 0)
206	            return 1;
207	        if (cmd[i + wlen] != '\0' && cmd[i + wlen] != ' ')
208	            return 1;           /* "dumpsters" must not pass as "dump" */
209	        return 0;
210	    }
211	
212	    /* Check whitelist first */
213	    for (int k = 0; s_allowed[k]; k++) {
214	        if (strcmp(name, s_allowed[k]) == 0)
215	            return 0;  /* allowed */
216	    }
217	
218	    /* Then check blacklist */
219	    for (int k = 0; s_blocked[k]; k++) {
220	        if (strcmp(name, s_blocked[k]) == 0)
221	            return 1;  /* blocked */
222	    }
223	    
224	    /* Default deny in allowlist mode */
225	    return 1;
226	#endif
227	}
