229	/* Read a /proc file into buffer, return bytes read */
230	static size_t read_proc_file(const char *path, char *buf, size_t buf_size)
231	{
232	    FILE *fp = fopen(path, "r");
233	    if (!fp) return 0;
234	    size_t n = fread(buf, 1, buf_size - 1, fp);
235	    buf[n] = '\0';
236	    fclose(fp);
237	    return n;
238	}
