250	/* Built-in "ps" — read /proc/<pid>/status for each pid */
251	static int builtin_ps(char *output, size_t output_size)
252	{
253	    DIR *d = opendir("/proc");
254	    if (!d) return ERROR;
255	
256	    size_t off = 0;
257	    off += snprintf(output + off, output_size - off,
258	                    "%-6s %-4s %-8s %-20s %s\n",
259	                    "PID", "PRI", "STACK", "STATUS", "NAME");
260	
261	    struct dirent *ent;
262	    while ((ent = readdir(d)) != NULL && off < output_size - 128) {
263	        /* Only numeric dirs are PIDs */
264	        if (ent->d_name[0] < '0' || ent->d_name[0] > '9')
265	            continue;
266	
267	        char path[128];
268	        char buf[512] = {0};
269	
270	        snprintf(path, sizeof(path), "/proc/%s/status", ent->d_name);
271	        if (read_proc_file(path, buf, sizeof(buf)) > 0) {
272	            /* Trim trailing newline */
273	            char *nl = strchr(buf, '\n');
274	            if (nl) *nl = '\0';
275	            off += snprintf(output + off, output_size - off,
276	                            "%-6s %s\n", ent->d_name, buf);
277	        }
278	    }
279	    closedir(d);
280	    return OK;
281	}
