283	/* Built-in "df" — statfs on common mount points */
284	static int builtin_df(char *output, size_t output_size)
285	{
286	    static const char *mounts[] = { "/", "/tmp", "/data", NULL };
287	    size_t off = 0;
288	    off += snprintf(output + off, output_size - off,
289	                    "%-12s %12s %12s %12s\n",
290	                    "Filesystem", "Total", "Used", "Free");
291	
292	    for (int i = 0; mounts[i]; i++) {
293	        struct statfs sfs;
294	        if (statfs(mounts[i], &sfs) == 0) {
295	            unsigned long total = (unsigned long)sfs.f_blocks * sfs.f_bsize;
296	            unsigned long avail = (unsigned long)sfs.f_bavail * sfs.f_bsize;
297	            unsigned long used  = total - avail;
298	            off += snprintf(output + off, output_size - off,
299	                            "%-12s %10luKB %10luKB %10luKB\n",
300	                            mounts[i], total / 1024, used / 1024, avail / 1024);
301	        }
302	        if (off >= output_size - 1) break;
303	    }
304	    return OK;
305	}
