330	/* Allowed path prefixes for file access (symlink escape protection) */
331	static const char *s_allowed_prefixes[] = {
332	    "/proc/", "/data/agent/", "/data/velaguard/", "/tmp/", NULL
333	};
334	
335	static bool is_path_allowed(const char *path)
336	{
337	    char resolved[PATH_MAX];
338	    /* Resolve symlinks to get the real path */
339	    if (realpath(path, resolved) == NULL) {
340	        /* If file doesn't exist, check the raw path */
341	        strncpy(resolved, path, sizeof(resolved) - 1);
342	        resolved[sizeof(resolved) - 1] = '\0';
343	    }
344	
345	    /* Normalise: strip trailing slash for comparison (except root "/") */
346	    size_t rlen = strlen(resolved);
347	    if (rlen > 1 && resolved[rlen - 1] == '/')
348	        resolved[--rlen] = '\0';
349	
350	    for (int i = 0; s_allowed_prefixes[i]; i++) {
351	        /* Compare against prefix with and without its trailing slash */
352	        size_t plen = strlen(s_allowed_prefixes[i]);
353	        /* Strip trailing slash from prefix for comparison */
354	        size_t cmp_len = (plen > 1 && s_allowed_prefixes[i][plen - 1] == '/')
355	            ? plen - 1 : plen;
356	        /* Allow exact match (the directory itself) or path inside it */
357	        if (strncmp(resolved, s_allowed_prefixes[i], cmp_len) == 0
358	            && (resolved[cmp_len] == '\0' || resolved[cmp_len] == '/'))
359	            return true;
360	    }
361	    return false;
362	}
