364	/* Built-in "cat" — read any readable file (with path restriction) */
365	static int builtin_cat(const char *path, char *output, size_t output_size)
366	{
367	    if (!path || !path[0]) return ERROR;
368	    if (!is_path_allowed(path)) {
369	        snprintf(output, output_size, "Access denied: path outside allowed directories");
370	        return ERROR;
371	    }
372	    size_t n = read_proc_file(path, output, output_size);
373	    return n > 0 ? OK : ERROR;
374	}
