376	/* Built-in "dmesg" — read kernel log via /dev/kmsg */
377	static int builtin_dmesg(char *output, size_t output_size)
378	{
379	    /* Try /dev/kmsg (NuttX kernel log device) */
380	    size_t n = read_proc_file("/dev/kmsg", output, output_size);
381	    if (n > 0)
382	        return OK;
383	
384	    /* Fallback: read syslog buffer via /proc/kmsg */
385	    n = read_proc_file("/proc/kmsg", output, output_size);
386	    if (n > 0)
387	        return OK;
388	
389	    snprintf(output, output_size, "(dmesg not available on this platform)");
390	    return OK;
391	}
