393	/* Built-in command via popen — execute a whitelisted command and capture output */
394	static int builtin_popen_cmd(const char *cmd, char *output, size_t output_size)
395	{
396	#ifdef CONFIG_SYSTEM_POPEN
397	    FILE *fp = popen(cmd, "r");
398	    if (!fp) {
399	        snprintf(output, output_size,
400	                 "Failed to execute: %s (%s)", cmd, strerror(errno));
401	        return ERROR;
402	    }
403	
404	    size_t n = fread(output, 1, output_size - 1, fp);
405	    output[n] = '\0';
406	    int status = pclose(fp);
407	    /* NuttX pclose often returns -1 for NSH builtins even with stdout. */
408	    if (n > 0) {
409	        return OK;
410	    }
411	    if (status != 0) {
412	        snprintf(output, output_size,
413	                 "Command failed with exit code %d", WEXITSTATUS(status));
414	        return ERROR;
415	    }
416	
417	    return OK;
418	#else
419	    (void)cmd;
420	    snprintf(output, output_size, "popen not available (enable CONFIG_SYSTEM_POPEN)");
421	    return ERROR;
422	#endif
423	}
