425	/* Built-in "ls" — list directory (with path restriction) */
426	static int builtin_ls(const char *path, char *output, size_t output_size)
427	{
428	    /* Strip trailing slash for display, but keep for opendir */
429	    char dir_buf[PATH_MAX];
430	    const char *dir = (path && path[0]) ? path : "/data/agent";
431	
432	    /* Normalise: remove trailing slash (except root "/") so path check works */
433	    strncpy(dir_buf, dir, sizeof(dir_buf) - 1);
434	    dir_buf[sizeof(dir_buf) - 1] = '\0';
435	    size_t dlen = strlen(dir_buf);
436	    if (dlen > 1 && dir_buf[dlen - 1] == '/')
437	        dir_buf[dlen - 1] = '\0';
438	
439	    if (!is_path_allowed(dir_buf) && !is_path_allowed(dir)) {
440	        snprintf(output, output_size, "Access denied: path outside allowed directories");
441	        return ERROR;
442	    }
443	
444	    DIR *d = opendir(dir_buf);
445	    if (!d) {
446	        snprintf(output, output_size, "Cannot open directory %s: %s",
447	                 dir_buf, strerror(errno));
448	        return ERROR;
449	    }
450	
451	    size_t off = 0;
452	    struct dirent *ent;
453	    while ((ent = readdir(d)) != NULL && off < output_size - 64) {
454	        off += snprintf(output + off, output_size - off, "%s\n", ent->d_name);
455	    }
456	    closedir(d);
457	    if (off == 0)
458	        snprintf(output, output_size, "(empty)");
459	    return OK;
460	}
