462	int tool_run_shell_execute(const char *input_json, char *output, size_t output_size)
463	{
464	    const char *command = NULL;
465	
466	    cJSON *root = cJSON_Parse(input_json);
467	    if (root) {
468	        cJSON *c = cJSON_GetObjectItem(root, "command");
469	        if (c && cJSON_IsString(c))
470	            command = c->valuestring;
471	    }
472	
473	    if (!command || command[0] == '\0') {
474	        snprintf(output, output_size, "{\"error\":\"Missing 'command' parameter\"}");
475	        cJSON_Delete(root);
476	        return ERROR;
477	    }
478	
479	    if (strlen(command) > SHELL_CMD_MAX) {
480	        snprintf(output, output_size, "{\"error\":\"Command too long (max %d)\"}", SHELL_CMD_MAX);
481	        cJSON_Delete(root);
482	        return ERROR;
483	    }
484	
485	    if (is_blocked(command)) {
486	        syslog(LOG_WARNING, "[%s] Blocked dangerous command: %s\n", TAG, command);
487	        snprintf(output, output_size, "{\"error\":\"Command '%s' is blocked for safety\"}", command);
488	        cJSON_Delete(root);
489	        return ERROR;
490	    }
491	
492	    syslog(LOG_INFO, "[%s] Executing: %s\n", TAG, command);
493	
494	    /* Heap-allocate output buffer to avoid stack overflow.
495	     * tool_run_shell_execute is called from parallel tool threads
496	     * (16KB stack) and SHELL_OUTPUT_MAX (4096) on stack would consume
497	     * too much of the available stack space. */
498	    char *cmd_buf = calloc(1, SHELL_OUTPUT_MAX);
499	    if (!cmd_buf) {
500	        snprintf(output, output_size, "{\"error\":\"OOM\"}");
501	        cJSON_Delete(root);
502	        return ERROR;
503	    }
504	    int ret = ERROR;
505	
506	    /* Skip leading spaces */
507	    while (*command == ' ') command++;
508	
509	    if (strcmp(command, "free") == 0 || strncmp(command, "free ", 5) == 0) {
510	        ret = builtin_free(cmd_buf, SHELL_OUTPUT_MAX);
511	    } else if (strcmp(command, "ps") == 0 || strncmp(command, "ps ", 3) == 0) {
512	        ret = builtin_ps(cmd_buf, SHELL_OUTPUT_MAX);
513	    } else if (strcmp(command, "df") == 0 || strncmp(command, "df ", 3) == 0) {
514	        ret = builtin_df(cmd_buf, SHELL_OUTPUT_MAX);
515	    } else if (strcmp(command, "uptime") == 0) {
516	        ret = builtin_uptime(cmd_buf, SHELL_OUTPUT_MAX);
517	    } else if (strcmp(command, "uname") == 0 || strncmp(command, "uname ", 6) == 0) {
518	        ret = builtin_uname(cmd_buf, SHELL_OUTPUT_MAX);
519	    } else if (strncmp(command, "cat ", 4) == 0) {
520	        const char *arg = command + 4;
521	        while (*arg == ' ') arg++;
522	        ret = builtin_cat(arg, cmd_buf, SHELL_OUTPUT_MAX);
523	    } else if (strncmp(command, "ls", 2) == 0) {
524	        const char *arg = command + 2;
525	        while (*arg == ' ') arg++;
526	        ret = builtin_ls(arg[0] ? arg : NULL, cmd_buf, SHELL_OUTPUT_MAX);
527	    } else if (strcmp(command, "dmesg") == 0 || strncmp(command, "dmesg ", 6) == 0) {
528	        ret = builtin_dmesg(cmd_buf, SHELL_OUTPUT_MAX);
529	    } else if (strncmp(command, "pm ", 3) == 0 || strcmp(command, "pm") == 0) {
530	        ret = builtin_popen_cmd(command, cmd_buf, SHELL_OUTPUT_MAX);
531	    } else if (strncmp(command, "am ", 3) == 0 || strcmp(command, "am") == 0) {
532	        ret = builtin_popen_cmd(command, cmd_buf, SHELL_OUTPUT_MAX);
533	    } else {
534	#ifdef CONFIG_SYSTEM_POPEN
535	        /* Execute via popen() - available when CONFIG_SYSTEM_POPEN is enabled.
536	         * Command has already passed security checks (is_blocked). */
537	        FILE *fp = popen(command, "r");
538	        if (fp) {
539	            size_t n = fread(cmd_buf, 1, SHELL_OUTPUT_MAX - 1, fp);
540	            cmd_buf[n] = '\0';
541	            int status = pclose(fp);
542	            /* NuttX popen/waitpid often returns -1 for NSH builtins even
543	             * when stdout is valid; treat captured output as success. */
544	            if (n > 0) {
545	                ret = OK;
546	            } else {
547	                ret = (status == 0) ? OK : ERROR;
548	            }
549	            if (ret != OK) {
550	                snprintf(cmd_buf, SHELL_OUTPUT_MAX,
551	                         "Command failed with exit code %d",
552	                         WEXITSTATUS(status));
553	            }
554	            syslog(LOG_INFO, "[%s] popen(%s) exit=%d, %zu bytes\n",
555	                   TAG, command, status, n);
556	        } else {
557	            syslog(LOG_ERR, "[%s] popen(%s) failed: %s\n",
558	                   TAG, command, strerror(errno));
559	            snprintf(cmd_buf, SHELL_OUTPUT_MAX,
560	                     "Failed to execute: %s (%s)", command, strerror(errno));
561	            ret = ERROR;
562	        }
563	#else
564	        /* popen() not available - only builtin commands work */
