  size_t out = 0;

  if (dst == NULL || cap == 0)
    {
      return VG_AI_ERR_ARG;
    }

  while (i < vlen)
    {
      unsigned char c = (unsigned char)v[i];
      size_t step;

      if (c < 0x20 || c == 0x7f)
        {
          return VG_AI_ERR_UTF8;
        }

      step = utf8_step(v + i, vlen - i);
      if (step == 0)
        {
          return VG_AI_ERR_UTF8;
        }

      if (out + step > cap)
        {
          break;
        }

      memcpy(dst + out, v + i, step);
      out += step;
      i += step;
    }

  dst[out] = '\0';
  return VG_AI_OK;
}

